import { test, expect } from '../framework/support/test.js';
import { LoginPage } from '../framework/pages/LoginPage.js';
test('ESS-A11Y-001: login shell exposes a meaningful document @accessibility', async ({ page }) => {
  // Open the configured login page through the reusable Page Object.
  await new LoginPage(page).open();
  // Assert the document has a meaningful user-facing title.
  await expect(page).toHaveTitle(/TaskyMed|login|sign/i);
});
